            try:
                grp = df.groupby(seg)[met].mean().dropna()
                if len(grp) > 10:
                    grp = grp.nlargest(10)
                result['segments'].append({
                    'segment_column': seg, 'metric_column': met,
                    'aggregation': 'mean', 'label': None,
