try:
    hc_vals = [996, 999, 994, 997, 1002, 1000, 1009, 945, 934, 918, 901, 885]
    hc_labels = ['Nov-2025','Dec-2025','Jan-2026','Feb-2026','Mar-2026','Apr-2026',
