    x = np.arange(len(hc_vals), dtype=float)
    y = np.array(hc_vals, dtype=float)
    slope, intercept, r_val, p_val, _ = stats.linregress(x, y)
    next_val = round(float(slope * len(hc_vals) + intercept), 1)
    result['forecast_points'].append({'period': 'Nov-2026_forecast', 'value': next_val})
    result['statistical_tests'].append({
        'test_name': 'headcount_monthly_trend_linregress',
        'statistic': round(float(slope), 4),
        'p_value': round(float(p_val), 4),
        'interpretation': (
            f'Monthly headcount linear trend: slope={slope:.4f} per month, '
            f'r={r_val:.3f}, p={p_val:.3g}; '
            f'{"significant downward trend" if p_val < 0.05 and slope < 0 else "no significant linear trend"}'
        )
    })
