try:
    anomaly_records = []
    for col in ['Annual_Salary', 'FTE']:
        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        shift = float(-s.min()) if s.min() < 0 else 0.0
        s_t = np.log1p(s + shift) if abs(skew) > 2 else s.copy()
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s_t) > 0.05:
            anomaly_records.append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(s.quantile(0.25)):.2f}–{float(s.quantile(0.75)):.2f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        if abs(skew) > 2:
            lo_orig = round(float(np.expm1(lo3) - shift), 2)
            hi_orig = round(float(np.expm1(hi3) - shift), 2)
        else:
            lo_orig = round(float(lo3), 2)
            hi_orig = round(float(hi3), 2)
        flagged_idx = s_t[mask].index
        for idx in flagged_idx:
            val = float(df.loc[idx, col])
            tv  = float(s_t[idx])
            sev = 'critical' if (tv < lo5 or tv > hi5) else \
                  'high'     if (tv < lo4 or tv > hi4) else 'medium'
            anomaly_records.append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': f'{lo_orig:.2f}–{hi_orig:.2f}',
                'severity': sev,
                'explanation': f'{col} value {val:.2f} lies outside expected range {lo_orig:.2f}–{hi_orig:.2f}'
            })
    n_unknown = int((df['left_date_unknown'] == 'yes').sum())
    if n_unknown > 0:
        anomaly_records.append({
            'column': 'Termination_Date', 'row_index': None, 'value': n_unknown,
            'expected_range': 'all terminated rows should have a date',
            'severity': 'medium',
            'explanation': (
                f'{n_unknown} rows have a terminated status but no termination date; '
                f'these are excluded from headcount and attrition calculations'
            )
        })
    result['anomalies'].extend(anomaly_records[:25])
except Exception:
    pass

