        s = df[col].dropna()
        if s.nunique() < 5:
            continue
        skew = float(s.skew())
        if abs(skew) > 2:
            shift = max(0.0, -float(s.min()) + 1.0)
            s_t = np.log1p(s + shift)
        else:
            s_t = s.copy()
            shift = 0.0
        q1, q3 = float(s_t.quantile(0.25)), float(s_t.quantile(0.75))
        iqr = q3 - q1
        lo3, hi3 = q1 - 3 * iqr, q3 + 3 * iqr
        lo4, hi4 = q1 - 4 * iqr, q3 + 4 * iqr
        lo5, hi5 = q1 - 5 * iqr, q3 + 5 * iqr
        mask = (s_t < lo3) | (s_t > hi3)
        if mask.sum() / len(s_t) > 0.05:
            result['anomalies'].append({
                'column': col, 'row_index': None, 'value': None,
                'expected_range': f'{float(s.min()):.2f}–{float(s.max()):.2f}',
                'severity': 'low',
                'explanation': f'{col} is heavy-tailed; extreme-value flagging skipped'
            })
            continue
        if abs(skew) > 2:
            lo_orig = round(float(np.expm1(lo3) - shift), 2)
            hi_orig = round(float(np.expm1(hi3) - shift), 2)
        else:
            lo_orig = round(lo3, 2)
            hi_orig = round(hi3, 2)
        exp_range = f'{lo_orig:.2f}–{hi_orig:.2f}'
        for idx in s_t[mask].index:
            if total_flags >= 25:
                break
            val = round(float(df.loc[idx, col]), 2)
            tv = float(s_t.loc[idx])
            if tv < lo5 or tv > hi5:
                sev = 'critical'
            elif tv < lo4 or tv > hi4:
                sev = 'high'
            else:
                sev = 'medium'
            result['anomalies'].append({
                'column': col, 'row_index': int(idx), 'value': val,
                'expected_range': exp_range, 'severity': sev,
                'explanation': f'{col} value {val:.2f} lies outside expected range {exp_range}'
            })
            total_flags += 1
